
'use server';
/**
 * @fileOverview A Genkit flow for updating the order of a single project document.
 * This flow uses the Firestore REST API to bypass client-side security rules.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { GoogleAuth } from 'google-auth-library';
import { firebaseConfig } from '@/firebase/config';

// Input schema: expects project ID and new order number.
const UpdateProjectOrderInputSchema = z.object({
  projectId: z.string(),
  order: z.number(),
});

// Output schema: returns a success status and an optional error message.
const UpdateProjectOrderOutputSchema = z.object({
  success: z.boolean(),
  error: z.string().optional(),
});

/**
 * A server-side function to update a project's order.
 * @param projectId The Firestore document ID of the project to update.
 * @param order The new order value.
 * @returns A promise that resolves with the result of the operation.
 */
export async function updateProjectOrder(
  projectId: string,
  order: number
): Promise<z.infer<typeof UpdateProjectOrderOutputSchema>> {
  return updateProjectOrderFlow({ projectId, order });
}

/**
 * A Genkit flow that updates a single project's order field using the REST API.
 */
const updateProjectOrderFlow = ai.defineFlow(
  {
    name: 'updateProjectOrderFlow',
    inputSchema: UpdateProjectOrderInputSchema,
    outputSchema: UpdateProjectOrderOutputSchema,
  },
  async ({ projectId, order }) => {
    const gcpProjectId = firebaseConfig.projectId;
    if (!gcpProjectId) {
      return { success: false, error: 'Google Cloud Project ID is not configured.' };
    }

    if (!projectId) {
      return { success: false, error: 'Project ID is required.' };
    }

    try {
      const auth = new GoogleAuth({
        scopes: 'https://www.googleapis.com/auth/datastore',
      });
      const client = await auth.getClient();

      // Construct the URL for the Firestore REST API PATCH method.
      const url = `https://firestore.googleapis.com/v1/projects/${gcpProjectId}/databases/(default)/documents/projects/${projectId}?updateMask.fieldPaths=order`;

      // The payload format for a PATCH request to update a single field.
      const payload = {
        fields: {
          order: {
            integerValue: order.toString(),
          },
        },
      };

      const response = await client.request({
        url,
        method: 'PATCH',
        data: payload,
      });
      
      if (response.status >= 200 && response.status < 300) {
        return { success: true };
      } else {
        const errorText = response.data ? JSON.stringify(response.data) : `Status code: ${response.status}`;
        console.error('Firestore REST API PATCH failed:', errorText);
        return { success: false, error: `Failed to update project order. ${errorText}` };
      }
    } catch (e: any) {
      console.error('An unexpected error occurred in updateProjectOrderFlow:', e);
      const errorMessage = e.response?.data?.error?.message || e.message || 'An unexpected server error occurred.';
      return {
        success: false,
        error: errorMessage,
      };
    }
  }
);
